<script setup lang="ts">
import {reactive} from 'vue'
import {useConfigurationPage} from '../hooks/useConfigurationPage'
import {time} from '../shared/types'
const props=defineProps<{level:number;special?:string}>(),vm=reactive(useConfigurationPage(props.level,props.special))
</script>
<template><a-card :title="special==='evaluation'?'评分评价区间':special==='settings'?'应用设置':(level===1?'公司':'项目')+'基础配置'">
