 <a-alert v-if="vm.error" :message="vm.error" type="error" show-icon />
 <a-space wrap style="margin:16px 0"><a-select v-if="level===2" v-model:value="vm.projectId" :options="vm.projects.map(p=>({value:p.id,label:p.name}))" placeholder="选择业务项目" style="width:230px" /><a-input-search v-model:value="vm.name" placeholder="按名称搜索" @search="vm.search" /><template v-if="!special"><a-select v-model:value="vm.importTarget" :options="[{value:'subjects',label:'条线科目导入'},{value:'basic',label:'检查内容导入'},{value:'task',label:'巡检配置导入'}]" style="width:180px" /><a-button @click="vm.downloadTemplate">下载模板</a-button><a-upload v-if="vm.can('quality-configuration','save')" :show-upload-list="false" :before-upload="vm.importFile" accept=".xlsx,.xls" :disabled="vm.importing"><a-button :loading="vm.importing">导入 Excel</a-button></a-upload></template></a-space>
 <a-tabs v-if="!special" v-model:activeKey="vm.kind"><a-tab-pane v-for="k in vm.configKinds" :key="k.value" :tab="k.label" /></a-tabs>
 <a-table :data-source="vm.rows" :loading="vm.loading" row-key="id" :pagination="{current:vm.current,total:vm.total,pageSize:20,showSizeChanger:false}" @change="(p:{current?:number})=>{vm.current=p.current||1;vm.load()}">
