 <a-table-column title="更新时间" key="time"><template #default="{record}">{{time(record.modifyTime)}}</template></a-table-column><a-table-column title="操作" key="actions"><template #default="{record}"><a-space><a-button v-if="vm.can('quality-configuration','save')" type="link" @click="vm.edit(record)">编辑</a-button><a-popconfirm v-if="vm.can('quality-configuration','delete')" title="删除此配置？" @confirm="vm.remove(record)"><a-button type="link" danger>删除</a-button></a-popconfirm></a-space></template></a-table-column>
