 <a-form-item v-if="vm.parentKind" label="所属上级" name="parentId" :rules="[{required:true,message:'请选择上级'}]"><a-select v-model:value="vm.form.parentId" :options="vm.options(vm.parentKind)" show-search option-filter-prop="label" /></a-form-item>
 <a-form-item v-if="vm.form.kind==='line'" label="业务板块"><a-select v-model:value="vm.form.data.categoryId" :options="vm.options('category')" allow-clear /></a-form-item>
